using System.Linq.Expressions;
using Microsoft.EntityFrameworkCore;
using ExampleApp.Common.Infrastructure.EntityFramework;
using ExampleApp.Common.Products;
using ExampleApp.Modules.Core.Domain.ContractImportItems.Entities;
using ExampleApp.Modules.Core.Domain.Products.Entities;
using ExampleApp.Modules.Core.Interop.Products.Dtos;

namespace ExampleApp.Modules.Core.Infrastructure.Products;

/// <summary>
/// ExampleVendor product-code mapping status read, as one translatable pipeline: the imported codes left joined
/// onto a per-code candidate summary, so the whole status list is a single SQL statement.
/// </summary>
internal static class ProductMappingStatusProjections
{
	private const int MaxDistinctProductPairs = 1_000;

	// S3776: every branching field below is one SQL CASE and must stay in this single expression tree.
#pragma warning disable S3776
	private static Expression<Func<MappingRow, ProductMappingStatusDto>> ToStatus =>
		row => new ProductMappingStatusDto
		{
			ExternalProductCode = row.Code,
			IsMapped = row.IsMapped,
			// Guarded on IsMapped: an unguarded Max returns an id while IsMapped is false.
			MappedProductId = row.IsMapped ? row.ActiveProductId : null,
			MappedProductName = row.IsMapped ? row.ActiveProductName : null,
			// The fallback needs IsSingleCandidate: Max(id) and Max(name) are independent aggregates,
			// so without the single-candidate guard they can name two different products.
			PairedProductId =
				row.IsMapped ? row.ActiveProductId
				: row.IsSingleCandidate ? row.AnyProductId
				: null,
			PairedProductName =
				row.IsMapped ? row.ActiveProductName
				: row.IsSingleCandidate ? row.AnyProductName
				: null,
			// Ambiguous is decided on the total count, not the active count. A NULL summary compares
			// false on every arm and falls through to no issue.
			PairingIssue =
				row.IsMapped ? null
				: row.IsAmbiguous ? ProductPairingIssue.Ambiguous
				: row.IsSingleCandidate ? ProductPairingIssue.ProductInactive
				: null,
		};
#pragma warning restore S3776

	public static IQueryable<ProductMappingStatusDto> Project(
		IQueryable<ContractImportItem> contractImportItems,
		IQueryable<Product> products
	)
	{
		// A code with no candidate gets a NULL summary row from the left join, and every count comparison
		// here is false under SQL three-valued logic - never a zero-count group, never a candidate.
		var rows = QueryImportedCodes(contractImportItems)
			.LeftJoin(
				QueryCandidateSummaries(products),
				code => code,
				summary => summary.Code,
				(code, summary) =>
					new MappingRow
					{
						Code = code,
						IsMapped = (int?)summary!.ActiveCount == 1,
						IsSingleCandidate = (int?)summary!.TotalCount == 1,
						IsAmbiguous = (int?)summary!.TotalCount > 1,
						ActiveProductId = summary!.ActiveProductId,
						ActiveProductName = summary!.ActiveProductName,
						AnyProductId = summary!.AnyProductId,
						AnyProductName = summary!.AnyProductName,
					}
			);

		return rows.Select(ToStatus)
			.OrderBy(status => EF.Functions.Collate(status.ExternalProductCode, ExampleAppCollations.Czech.Name));
	}

	private static IQueryable<string> QueryImportedCodes(IQueryable<ContractImportItem> contractImportItems)
	{
		// The cap bounds the distinct (code, mode) pairs, before the composite expansion doubles them.
		var pairs = contractImportItems
			.Where(item => item.ProductCode != null && item.ProductCode != string.Empty)
			.Select(item => new { item.ProductCode, item.CommissionModeType })
			.Distinct()
			.OrderBy(pair => pair.ProductCode)
			.ThenBy(pair => pair.CommissionModeType)
			.Take(MaxDistinctProductPairs);

		return pairs
			.Select(pair => pair.ProductCode!)
			.Union(
				pairs
					.Where(pair => pair.CommissionModeType != null && pair.CommissionModeType != string.Empty)
					.Select(pair => pair.ProductCode + "|" + pair.CommissionModeType)
			);
	}

	private static IQueryable<CandidateSummary> QueryCandidateSummaries(IQueryable<Product> products)
	{
		return QueryMappingCandidates(products)
			.GroupBy(candidate => candidate.Code)
			.Select(group => new CandidateSummary
			{
				Code = group.Key,
				TotalCount = group.Count(),
				ActiveCount = group.Sum(candidate => candidate.IsActive ? 1 : 0),
				ActiveProductId = group.Max(candidate => candidate.IsActive ? (long?)candidate.ProductId : null),
				ActiveProductName = group.Max(candidate => candidate.IsActive ? candidate.ProductName : null),
				AnyProductId = group.Max(candidate => (long?)candidate.ProductId),
				AnyProductName = group.Max(candidate => candidate.ProductName),
			});
	}

	private static IQueryable<MappingCandidate> QueryMappingCandidates(IQueryable<Product> products)
	{
		// `.Code` is an extension property and expression trees reject it (CS9296); read it into a local first.
		var mappingSource = ProductExternalMappingSource.ExampleVendor.Code;

		// An inactive mapping still makes the product a candidate - it is what turns "unmapped" into
		// "ProductInactive" - so the mapping flag is aggregated, never filtered on.
		// EF.Property reads the strongly typed id server side; `product.Id.Value` is client-side and EF
		// then refuses the Union in QueryImportedCodes.
		return products
			.SelectMany(product =>
				product
					.ExternalMappings.Where(mapping => mapping.Source == mappingSource)
					.Select(mapping => new
					{
						Code = mapping.ExternalProductCode,
						ProductId = EF.Property<long>(product, nameof(product.Id)),
						ProductName = product.Name,
						ProductIsActive = product.IsActive,
						MappingIsActive = mapping.IsActive,
					})
			)
			.GroupBy(row => new
			{
				row.Code,
				row.ProductId,
				row.ProductName,
				row.ProductIsActive,
			})
			// PostgreSQL has no max(boolean); the integer form is the aggregate that translates.
			.Select(group => new MappingCandidate
			{
				Code = group.Key.Code,
				ProductId = group.Key.ProductId,
				ProductName = group.Key.ProductName,
				IsActive = group.Key.ProductIsActive && group.Max(row => row.MappingIsActive ? 1 : 0) == 1,
			});
	}

	private sealed record MappingCandidate
	{
		public required string Code { get; init; }
		public required long ProductId { get; init; }
		public required string ProductName { get; init; }
		public required bool IsActive { get; init; }
	}

	private sealed record CandidateSummary
	{
		public required string Code { get; init; }
		public required int TotalCount { get; init; }
		public required int ActiveCount { get; init; }
		public long? ActiveProductId { get; init; }
		public string? ActiveProductName { get; init; }
		public long? AnyProductId { get; init; }
		public string? AnyProductName { get; init; }
	}

	private sealed record MappingRow
	{
		public required string Code { get; init; }
		public required bool IsMapped { get; init; }
		public required bool IsSingleCandidate { get; init; }
		public required bool IsAmbiguous { get; init; }
		public long? ActiveProductId { get; init; }
		public string? ActiveProductName { get; init; }
		public long? AnyProductId { get; init; }
		public string? AnyProductName { get; init; }
	}
}
