using AppFx.Workflows.Workflows;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;
using ExampleApp.Modules.Core.Domain.Workflows;
using ExampleApp.Modules.Core.Infrastructure.Infrastructure.EF;

namespace ExampleApp.Modules.Core.IntegrationTests.Workflows;

internal sealed class WorkflowSingletonReservationTests
{
	private static readonly DateTimeOffset FixedNow = new(2026, 9, 18, 8, 0, 0, TimeSpan.Zero);

	private const string SingletonKeyIndexName = "app_workflow_lock";
	private const string UniqueViolation = "23505";

	[Test]
	[CoreWorkflowsTestHostContext]
	public async Task CompetingStarts_SharingSingletonKey_LeaveExactlyOneActiveWorkflow(
		IServiceScopeFactory scopeFactory,
		CoreDbContext dbContext
	)
	{
		var singletonKey = NewSingletonKey();
		using var startTogether = new Barrier(2);

		var attempts = await Task.WhenAll(
			Task.Run(() => StartAsync(scopeFactory, singletonKey, startTogether)),
			Task.Run(() => StartAsync(scopeFactory, singletonKey, startTogether))
		);

		var winners = attempts.Where(x => x.Failure is null).ToArray();
		var losers = attempts.Where(x => x.Failure is not null).ToArray();

		await Assert.That(winners.Length).IsEqualTo(1);
		await Assert.That(losers.Length).IsEqualTo(1);

		var postgresFailure = losers[0].Failure!.InnerException as PostgresException;
		await Assert.That(postgresFailure).IsNotNull();
		await Assert.That(postgresFailure!.SqlState).IsEqualTo(UniqueViolation);
		await Assert.That(postgresFailure.ConstraintName).IsEqualTo(SingletonKeyIndexName);

		var reserved = await ReservedIdsAsync(dbContext, singletonKey);
		await Assert.That(reserved.Count).IsEqualTo(1);
		await Assert.That(reserved[0]).IsEqualTo(winners[0].WorkflowId);
		await Assert.That(reserved).DoesNotContain(losers[0].WorkflowId);
	}

	[Test]
	[CoreWorkflowsTestHostContext]
	public async Task WorkflowWaitingForUserAction_KeepsItsReservation(
		IServiceScopeFactory scopeFactory,
		CoreDbContext dbContext
	)
	{
		var singletonKey = NewSingletonKey();
		var parked = await StartAsync(scopeFactory, singletonKey, WorkflowStatus.WaitingUserAction);
		await Assert.That(parked.Failure).IsNull();

		var second = await StartAsync(scopeFactory, singletonKey, WorkflowStatus.Running);

		await Assert.That(second.Failure).IsNotNull();
		await Assert.That((second.Failure!.InnerException as PostgresException)?.ConstraintName)
			.IsEqualTo(SingletonKeyIndexName);

		var reserved = await ReservedIdsAsync(dbContext, singletonKey);
		await Assert.That(reserved.Count).IsEqualTo(1);
		await Assert.That(reserved[0]).IsEqualTo(parked.WorkflowId);
	}

	[Test]
	[CoreWorkflowsTestHostContext]
	public async Task CompletedWorkflow_ReleasesReservation_AndItsIdStopsResolving(
		IServiceScopeFactory scopeFactory,
		CoreDbContext dbContext,
		IWorkflowStore workflowStore
	)
	{
		var singletonKey = NewSingletonKey();
		var first = await StartAsync(scopeFactory, singletonKey, WorkflowStatus.Running);
		await Assert.That(first.Failure).IsNull();

		await dbContext
			.Set<WorkflowBase>()
			.Where(x => x.Id == first.WorkflowId)
			.ExecuteDeleteAsync(CancellationToken.None);

		var second = await StartAsync(scopeFactory, singletonKey, WorkflowStatus.Running);

		await Assert.That(second.Failure).IsNull();
		await Assert.That(second.WorkflowId).IsNotEqualTo(first.WorkflowId);

		var reserved = await ReservedIdsAsync(dbContext, singletonKey);
		await Assert.That(reserved.Count).IsEqualTo(1);
		await Assert.That(reserved[0]).IsEqualTo(second.WorkflowId);
		await Assert.That(await workflowStore.GetAsync<EchoWorkflow>(first.WorkflowId, CancellationToken.None))
			.IsNull();
	}

	private static string NewSingletonKey() => $"Core.Echo.Singleton.{Guid.NewGuid():N}";

	private static Task<StartAttempt> StartAsync(
		IServiceScopeFactory scopeFactory,
		string singletonKey,
		WorkflowStatus workflowStatus
	) => StartAsync(scopeFactory, singletonKey, startTogether: null, workflowStatus);

	private static Task<StartAttempt> StartAsync(
		IServiceScopeFactory scopeFactory,
		string singletonKey,
		Barrier startTogether
	) => StartAsync(scopeFactory, singletonKey, startTogether, WorkflowStatus.Running);

	private static async Task<StartAttempt> StartAsync(
		IServiceScopeFactory scopeFactory,
		string singletonKey,
		Barrier? startTogether,
		WorkflowStatus workflowStatus
	)
	{
		var workflowId = WorkflowId.From(Guid.CreateVersion7());
		using var scope = scopeFactory.CreateScope();
		var dbContext = scope.ServiceProvider.GetRequiredService<CoreDbContext>();

		var workflow = new EchoWorkflow
		{
			Id = workflowId,
			CreatedAt = FixedNow,
			WorkflowStatus = workflowStatus,
			State = new EchoWorkflowStateV5 { Message = "ahoj", MessageLength = 4 },
		};
		var entry = dbContext.Add(workflow);
		entry.Property(nameof(WorkflowBase.SingletonKey)).CurrentValue = singletonKey;

		startTogether?.SignalAndWait();

		try
		{
			await dbContext.SaveChangesAsync(CancellationToken.None);
			return new StartAttempt(workflowId, Failure: null);
		}
		catch (DbUpdateException exception)
		{
			return new StartAttempt(workflowId, exception);
		}
	}

	private static async Task<IReadOnlyList<WorkflowId>> ReservedIdsAsync(CoreDbContext dbContext, string singletonKey)
	{
		dbContext.ChangeTracker.Clear();
		return await dbContext
			.Set<WorkflowBase>()
			.Where(x => x.SingletonKey == singletonKey)
			.Select(x => x.Id)
			.ToListAsync(CancellationToken.None);
	}

	private readonly record struct StartAttempt(WorkflowId WorkflowId, DbUpdateException? Failure);
}
